{
  "vulnerable_symbols": [
    "axios.post"
  ],
  "trigger": "应用将外部可控的 Blob/File 对象（type 含 CRLF）加入 FormData 并通过 axios.post 发送 multipart 请求。",
  "preconditions": [
    "运行在 Node.js 环境并触发 axios 的 formDataToStream 编码路径",
    "FormData 中的 Blob/File-like 对象的 type（或 name）由外部输入控制且未清理 CRLF"
  ],
  "exploit_evidence": [],
  "fixed_version": "1.15.1",
  "summary_zh": "axios 发送 FormData 时未过滤 Blob.type 的 CRLF，可注入 multipart 头，升级 1.15.1。"
}
